-- Exames que todo homem deve fazer a partir dos 30 anos
insert into public.posts (slug, title, subtitle, excerpt, body, cover_image_url, cover_image_alt, category_id, author_id, kind, faq, quiz, status, publish_at, reading_time, seo_title, seo_description)
values (
  $t$exames-que-todo-homem-deve-fazer-a-partir-dos-30-anos$t$,
  $t$Exames que todo homem deve fazer a partir dos 30 anos$t$,
  $t$A lista de exames por faixa etária, o que cada um mede e por que quem sustenta uma casa não pode empurrar o check-up para o ano que vem.$t$,
  $t$Pressão, glicemia, colesterol, próstata, saúde mental: a lista por faixa etária e por que quem tem filho não pode adiar o check-up.$t$,
  $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Você tem 30 e poucos anos, trabalha o dia inteiro, chega em casa e ainda dá conta das crianças. Dor nas costas é normal, cansaço é normal, aquela azia depois do almoço também é normal. O problema é que o corpo do homem avisa pouco: pressão alta, açúcar no sangue e colesterol fora da faixa não doem, e muitos pais só descobrem que algo estava errado quando o susto já chegou."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Este artigo lista os exames que o homem deve fazer a partir dos 30 anos, explica o que cada um mede, mostra como encaixar tudo na agenda de quem trabalha e tem filho pequeno e termina com o Semáforo do Pai para você saber a hora de não esperar. Se a sua esposa está grávida ou o bebê acabou de chegar, vale ler junto com a "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/rotina-do-pai-nos-primeiros-30-dias-do-bebe", "class": null, "rel": null, "target": null}}], "text": "rotina do pai nos primeiros 30 dias do bebê"}, {"type": "text", "text": ": cuidar de você é parte do plano."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Por que o pai não pode adiar o check-up"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Quando você era solteiro, adoecer era um problema seu. Agora tem gente que depende da sua saúde para comer, estudar e dormir tranquila. O provedor que se cuida está protegendo a casa, não sendo vaidoso. É a mesma lógica da reserva de emergência que você monta no "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/orcamento-familiar-para-quem-vai-ser-pai", "class": null, "rel": null, "target": null}}], "text": "orçamento familiar"}, {"type": "text", "text": ": você não espera a crise chegar para começar a se preparar."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Há outro motivo, mais simples: as principais causas de morte do homem adulto no Brasil, como infarto, AVC e alguns tipos de câncer, têm fatores que podem ser identificados cedo com exames baratos ou gratuitos. Quem mede, decide com tempo. Quem não mede, descobre tarde."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que medir já aos 30 anos"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A base do check-up do homem a partir dos 30 é curta e cabe em uma manhã de jejum. Converse com seu médico, mas esta é a lista que costuma aparecer em toda consulta de rotina:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Pressão arterial: medida em toda consulta, pelo menos uma vez por ano. É o exame mais barato e mais ignorado."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Glicemia em jejum e, quando o médico pedir, hemoglobina glicada: mostram como o seu corpo está lidando com o açúcar."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Perfil lipídico (colesterol total, HDL, LDL e triglicérides): mede a gordura no sangue, que entope artéria em silêncio."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Hemograma completo: anemia, infecção e alterações que merecem investigação."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Peso, altura e circunferência abdominal: a fita métrica na cintura diz muito sobre o risco cardíaco."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Avaliação de pele, dentes e visão: dermatologista, dentista e oftalmologista entram no calendário pelo menos a cada um ou dois anos."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Se você já treina ou pretende começar o "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/treino-de-20-minutos-em-casa-para-pais-sem-tempo", "class": null, "rel": null, "target": null}}], "text": "treino de 20 minutos em casa"}, {"type": "text", "text": ", leve o resultado desses exames ao médico antes. Pressão e glicemia em dia tornam o esforço mais seguro, e o médico pode liberar o treino com mais tranquilidade."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Dos 40 em diante: o que entra na lista"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A partir dos 40, a conversa com o médico fica mais detalhada. Além de repetir tudo o que você já fazia, costumam entrar na avaliação a função dos rins (creatinina e exame de urina), a função do fígado, os hormônios da tireoide e, dependendo do histórico, um eletrocardiograma e exames de imagem. Se há diabetes, obesidade ou doença do coração na família, o médico pode antecipar alguns desses pedidos."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Entre 45 e 50 anos começa a avaliação do intestino, com pesquisa de sangue nas fezes ou colonoscopia conforme a orientação profissional. Não é agradável, mas pega pólipos antes de virarem problema sério. Um pai que pretende ver os netos crescerem não pula essa etapa."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Próstata: quando começar a conversa"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A próstata é o assunto que o homem mais evita e o que mais rende piada no churrasco. Deixe a piada para o "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/cortes-de-carne-para-churrasco-guia-do-pai-iniciante", "class": null, "rel": null, "target": null}}], "text": "churrasco"}, {"type": "text", "text": " e leve o tema a sério no consultório. A orientação geral é conversar com o urologista por volta dos 50 anos; quem tem pai ou irmão com câncer de próstata começa mais cedo, por volta dos 45. Quem decide se faz o exame de sangue (PSA), o exame clínico ou os dois é o médico, a partir do seu histórico. O que você não pode fazer é decidir sozinho que não precisa."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Dificuldade para urinar, jato fraco, levantar várias vezes à noite ou sangue na urina não esperam a idade da tabela. Com qualquer um desses sinais, marque a consulta agora."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Saúde mental também é exame"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Sono ruim, irritação constante, desânimo que não passa e aquela sensação de estar sempre no limite não são bobagem: são sinais que omédico precisa ouvir. O pai que explode com os filhos e depois se culpa, como descrevemos em "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/como-dar-limites-sem-gritar-autoridade-com-calma", "class": null, "rel": null, "target": null}}], "text": "como dar limites sem gritar"}, {"type": "text", "text": ", muitas vezes está exausto, ansioso ou deprimido, e não sabe. Conte isso na consulta com a mesma naturalidade com que fala de dor no joelho."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Também vale observar o uso de álcool. Beber todo dia para relaxar, mesmo pouco, é um dado clínico. O médico não vai julgar; vai ajudar. E a sua esposa, que convive com você todos os dias, costuma perceber a mudança antes de você. Ouça o que ela diz, da mesma forma que o "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/como-ser-um-marido-presente-depois-que-o-bebe-chega", "class": null, "rel": null, "target": null}}], "text": "marido presente"}, {"type": "text", "text": " espera que ela ouça os cuidados dele."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Como organizar o check-up sem perder dias de trabalho"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "O check-up do homem cabe em duas saídas curtas. A primeira é a consulta, de preferência no mesmo médico todo ano, para ele acompanhar a evolução. A segunda é a coleta de sangue em jejum, logo cedo, antes do expediente. O retorno com os resultados pode ser presencial ou por telemedicina, dependendo do serviço. Marque tudo no mês do seu aniversário: fica fácil lembrar e o calendário se repete sozinho."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Pelo SUS, a Unidade Básica de Saúde do bairro faz a consulta de rotina e pede os exames básicos; pelo plano, o clínico geral ou o médico de família é a porta de entrada. Guarde os resultados em uma pasta ou no celular. Comparar o exame deste ano com o do ano passado vale mais do que qualquer número isolado. Outros temas de saúde do homem estão na seção "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/categoria/corpo-e-saude-do-homem", "class": null, "rel": null, "target": null}}], "text": "Corpo e saúde do homem"}, {"type": "text", "text": "."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Semáforo do pai: sinais do corpo"}]}, {"type": "callout", "attrs": {"tone": "ok"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sinal verde: você faz consulta e exames de sangue uma vez por ano, a pressão fica dentro da faixa normal, mantém peso estável, dorme razoavelmente e não tem histórico familiar de doença grave. Continue com o calendário anual e com a atividade física."}]}]}, {"type": "callout", "attrs": {"tone": "warn"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sinal de atenção: pressão medida acima do normal em mais de uma ocasião, glicemia ou colesterol no limite, ganho de peso na cintura, cansaço que não melhora com descanso, ronco forte ou sono que não repara. Marque a consulta este mês e leve os resultados antigos."}]}]}, {"type": "callout", "attrs": {"tone": "bad"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sinal de alerta: dor ou aperto no peito, falta de ar em esforço pequeno, dormência de um lado do corpo, sangue na urina ou nas fezes, perda de peso sem explicação, ou pensamentos de que a família estaria melhor sem você. Não espere a consulta de rotina: vá a um pronto atendimento ou procure o médico hoje; em caso de sofrimento emocional, o CVV atende pelo 188, dia e noite."}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Tabela: o check-up do homem por faixa etária"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Exame ou avaliação"}]}]}, {"type": "tableHeader", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A partir de"}]}]}, {"type": "tableHeader", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Frequência habitual"}]}]}, {"type": "tableHeader", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "O que mede"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Pressão arterial"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "30 anos (ou antes)"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Toda consulta, pelo menos 1 vez ao ano"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Risco de infarto, AVC e doença renal"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Glicemia em jejum"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "30 anos"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Anual, ou conforme o médico"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Pré-diabetes e diabetes"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Perfil lipídico"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "30 anos"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Anual a cada 2 anos"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Colesterol e triglicérides"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Hemograma e urina"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "30 anos"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Anual"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Anemia, infecção, rins"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Creatinina, fígado e tireoide"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "40 anos"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Conforme o médico"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Função de rins, fígado e tireoide"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Intestino (sangue oculto ou colonoscopia)"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "45 a 50 anos"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Conforme o resultado"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Pólipos e câncer colorretal"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Próstata (conversa com urologista)"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "50 anos (45 com histórico)"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Definida pelo médico"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Alterações da próstata"}]}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A tabela é um ponto de partida, não uma receita. Quem define o seu calendário é o médico que conhece o seu histórico, o seu peso e a sua família. Se a sua esposa está no "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/vai-ser-pai-guia-do-primeiro-trimestre-para-o-homem", "class": null, "rel": null, "target": null}}], "text": "primeiro trimestre da gravidez"}, {"type": "text", "text": ", aproveite as idas ao pré-natal para marcar a sua própria consulta: o hábito de cuidar da saúde começa a dois."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Checklist do pai: check-up anual"}]}, {"type": "taskList", "content": [{"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Marcar consulta de rotina no mês do aniversário"}]}]}, {"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Colher sangue em jejum na primeira hora da manhã"}]}]}, {"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Levar os resultados do ano anterior para comparar"}]}]}, {"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Contar ao médico sono, humor, álcool e histórico da família"}]}]}, {"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Anotar a próxima data no calendário da casa"}]}]}, {"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ficar atento aos sinais do semáforo acima"}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Fazer exame não é sinal de fraqueza; é sinal de que você entendeu o tamanho da sua missão. O homem que mede a pressão, cuida do sono e ouve o médico está dizendo aos filhos, sem palavras, que pretende estar por perto por muito tempo. Marque a consulta esta semana. É uma decisão pequena que protege tudo o que você construiu."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Continue lendo: "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/treino-de-20-minutos-em-casa-para-pais-sem-tempo", "class": null, "rel": null, "target": null}}], "text": "Treino de 20 minutos em casa para pais sem tempo"}, {"type": "text", "text": ", "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/orcamento-familiar-para-quem-vai-ser-pai", "class": null, "rel": null, "target": null}}], "text": "Orçamento familiar para quem vai ser pai: passo a passo"}, {"type": "text", "text": ", "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/como-ser-um-marido-presente-depois-que-o-bebe-chega", "class": null, "rel": null, "target": null}}], "text": "Como ser um marido presente depois que o bebê chega"}, {"type": "text", "text": ", "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/rotina-do-pai-nos-primeiros-30-dias-do-bebe", "class": null, "rel": null, "target": null}}], "text": "Rotina do pai nos primeiros 30 dias do bebê"}, {"type": "text", "text": ", "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/como-segurar-um-recem-nascido-com-seguranca", "class": null, "rel": null, "target": null}}], "text": "Como segurar um recém-nascido com segurança (e sem medo)"}, {"type": "text", "text": " e "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/kit-basico-de-ferramentas-para-a-casa", "class": null, "rel": null, "target": null}}], "text": "Kit básico de ferramentas para a casa: o que todo pai precisa ter"}, {"type": "text", "text": "."}]}]}$body$::jsonb,
  $t$https://images.unsplash.com/photo-1666887360680-9dc27a1d2753?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&q=80&w=1080$t$,
  $t$Homem sentado à mesa tendo a pressão arterial medida por um profissional de saúde durante uma consulta$t$,
  (select id from public.categories where slug = $t$corpo-e-saude-do-homem$t$ and parent_id is null limit 1),
  (select id from public.profiles where display_name = 'Equipe Vocação de Pai' limit 1),
  'artigo',
  $faq$[{"question": "Preciso fazer check-up mesmo sem sentir nada?", "answer": "Sim. Pressão alta, glicemia elevada e colesterol fora da faixa não dão sintoma por anos. O exame existe justamente para pegar o problema antes de ele aparecer. Converse com seu médico sobre a frequência certa para o seu caso."}, {"question": "Com que idade começa o exame de próstata?", "answer": "A recomendação geral é conversar com o urologista por volta dos 50 anos, ou antes (por volta dos 45) se houver pai ou irmão com câncer de próstata. Quem decide quando começar e qual exame fazer é o médico, a partir do seu histórico."}, {"question": "Posso fazer os exames pelo SUS?", "answer": "Sim. A Unidade Básica de Saúde do seu bairro faz a consulta de rotina, mede pressão e pede os exames de sangue básicos. Leve o cartão do SUS e, se tiver, os resultados antigos para comparar."}, {"question": "Quanto tempo leva um check-up completo?", "answer": "Normalmente uma consulta de 30 minutos, uma manhã para colher sangue em jejum e uma consulta de retorno. Com a agenda organizada, cabe em duas saídas rápidas do trabalho ao longo de um mês."}, {"question": "Cansaço e irritação entram no check-up?", "answer": "Entram. Sono ruim, ansiedade constante e desânimo que não passa devem ser contados ao médico na consulta. Saúde mental faz parte do exame do homem, e existe tratamento com acompanhamento profissional."}]$faq$::jsonb,
  $quiz$[{"question": "Qual destes problemas costuma passar anos sem dar sintoma?", "options": ["Pressão alta", "Dor de dente", "Torção no tornozelo", "Gripe"], "correct": 0, "explanation": "A hipertensão é silenciosa: na maior parte dos casos só aparece em exame de rotina, por isso medir a pressão todo ano faz diferença."}, {"question": "O que o exame de glicemia em jejum mede?", "options": ["A gordura no sangue", "O açúcar no sangue", "A função dos rins", "O nível de ferro"], "correct": 1, "explanation": "A glicemia mede o açúcar no sangue e ajuda a identificar pré-diabetes e diabetes, que avançam sem aviso."}, {"question": "Quando a conversa sobre próstata deve começar mais cedo?", "options": ["Quando o homem pratica esporte", "Quando há pai ou irmão com câncer de próstata", "Quando o homem tem mais de dois filhos", "Nunca antes dos 60"], "correct": 1, "explanation": "Histórico familiar antecipa a conversa com o urologista para por volta dos 45 anos, segundo as orientações gerais."}, {"question": "O que fazer com um resultado de exame alterado?", "options": ["Repetir sozinho daqui a um ano", "Pesquisar na internet e tomar remédio por conta", "Levar ao médico para interpretar e decidir o próximo passo", "Ignorar se não houver sintoma"], "correct": 2, "explanation": "Resultado alterado se discute com o médico, que conhece seu histórico e decide se repete, investiga ou trata."}]$quiz$::jsonb,
  'published',
  now(),
  8,
  $t$Exames que todo homem deve fazer a partir dos 30 anos$t$,
  $t$Lista de exames por faixa etária para o homem: pressão, glicemia, colesterol, próstata e saúde mental. O check-up que o pai não pode adiar.$t$
)
on conflict (slug) do nothing;

-- Cortes de carne para churrasco: guia do pai iniciante
insert into public.posts (slug, title, subtitle, excerpt, body, cover_image_url, cover_image_alt, category_id, author_id, kind, faq, quiz, status, publish_at, reading_time, seo_title, seo_description)
values (
  $t$cortes-de-carne-para-churrasco-guia-do-pai-iniciante$t$,
  $t$Cortes de carne para churrasco: guia do pai iniciante$t$,
  $t$Picanha, fraldinha, maminha e costela explicadas para quem vai assumir a churrasqueira pela primeira vez, com quantidade por pessoa, fogo e segurança.$t$,
  $t$Picanha, fraldinha, costela, maminha: o que escolher, quanto comprar por pessoa, como preparar o fogo e os erros que arruínam a carne.$t$,
  $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Você aceitou fazer o churrasco de domingo e agora está parado na frente do balcão do açougue sem saber a diferença entre picanha e maminha. A família vai chegar, o sogro vai opinar, e você não quer servir carne dura ou passar a tarde brigando com o fogo. Calma: churrasco bom não é mágica, é escolha certa de corte e paciência com a brasa."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Este guia explica os cortes que não decepcionam, quanto comprar por pessoa, como acender e controlar o fogo, como dar o ponto e quais erros arruínam a carne do iniciante. Também fala de segurança, porque churrasco de pai tem criança correndo por perto. Se o seu filho ainda é pequeno, o jeito certo de carregá-lo enquanto cuida da grelha está em "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/como-segurar-um-recem-nascido-com-seguranca", "class": null, "rel": null, "target": null}}], "text": "como segurar um recém-nascido com segurança"}, {"type": "text", "text": ": na prática, bebê e churrasqueira não ficam no mesmo braço."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Os cortes que não decepcionam"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "O açougue tem dezenas de nomes, mas para começar você precisa dominar quatro cortes. Cada um tem personalidade, e saber isso evita frustração:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Picanha: a capa de gordura é a assinatura. Peça peça inteira de até 1,2 kg (acima disso costuma vir com parte do coxão duro). Vai para a grelha em fatias grossas ou inteira, com a gordura para cima no começo."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Fraldinha: fibras longas, gordura entremeada, muito sabor. Perdoa o iniciante: aceita fogo médio e continua macia. Corte sempre contra as fibras na hora de servir."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Maminha: a ponta da alcatra, macia e mais magra. Fica ótima inteira, em fogo médio, descansando antes de fatiar."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Costela: o corte da paciência. Pede fogo baixo e horas de grelha, com o osso para baixo. Quando desprende do osso, está pronta. Não é o corte para o seu primeiro churrasco apressado, mas é o que mais reúne a família em volta do fogo."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Para completar, linguiça toscana, coração de frango e pão de alho seguram a fome enquanto a carne principal fica pronta. Asa e coxinha de frango são opções econômicas que as crianças adoram. Se o dinheiro está curto neste mês, vale a lógica do "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/orcamento-familiar-para-quem-vai-ser-pai", "class": null, "rel": null, "target": null}}], "text": "orçamento familiar"}, {"type": "text", "text": ": um corte bom em quantidade certa vale mais do que três cortes medianos sobrando."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Quanto comprar por pessoa"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A conta que não falha: de 400 a 500 gramas de carne crua por adulto, quando há acompanhamentos; em torno de 200 gramas por criança. Churrasco longo, de tarde inteira, sobe para 600 gramas por adulto. Divida a quantidade total entre um corte principal (cerca de 60%) e as entradas (linguiça, frango, pão de alho). Compre no dia ou na véspera e deixe na geladeira até a hora de temperar."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Um exemplo prático: para oito adultos e quatro crianças, cerca de 4 kg de carne no total, sendo 2,5 kg do corte principal e o resto em linguiça e frango. Sobrar um pouco é melhor do que faltar, mas a sobra tem de ir para a geladeira rápido."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Como escolher a carne no açougue"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Carne boa tem cor viva (vermelho vivo no boi, rosado no porco e no frango), gordura branca ou levemente amarelada e cheiro limpo. Fuja de pedaços escurecidos nas bordas, gordura cinzenta ou líquido acumulado na bandeja. Pergunte ao açougueiro o que chegou fresco e peça para ele limpar o excesso de nervo: um bom profissional orienta, e esse relacionamento vale tanto quanto a ferramenta certa na oficina, como no "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/kit-basico-de-ferramentas-para-a-casa", "class": null, "rel": null, "target": null}}], "text": "kit básico de ferramentas"}, {"type": "text", "text": "."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Carne embalada a vácuo também é boa opção: costuma ser mais padronizada e dura mais na geladeira. Abra a embalagem 30 minutos antes de temperar para a carne respirar e perder o cheiro do vácuo."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O fogo: carvão, altura e paciência"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "O erro número um do iniciante é colocar a carne na chama. Chama queima por fora e deixa cru por dentro. O que você quer é brasa: carvão cinza por cima e vermelho por dentro. Para chegar lá, acenda o carvão com acendedor próprio ou chaminé de ignição (nunca álcool líquido), espere de 30 a 40 minutos e só então leve a carne. Esse tempo de espera é o momento de preparar a mesa e conversar com os convidados."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Altura da grelha é o seu controle de temperatura. Cortes finos e linguiça ficam perto da brasa, por pouco tempo; peças inteiras e costela ficam no alto, por mais tempo. Se a mão aberta sobre a grelha aguenta 3 segundos, o fogo está forte; 6 segundos, médio; mais de 8, fraco. Não jogue água na brasa para controlar: isso levanta cinza e apaga de vez."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Sal, ponto e descanso da carne"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Tempere com sal grosso na hora de levar à grelha, nos cortes grossos, ou com sal fino na hora de servir, nos finos. Não fure a carne com garfo: use pegador. Vire poucas vezes. O ponto você aprende com a mão: carne mal passada cede como a base do polegar relaxado; ao ponto, resiste um pouco mais; bem passada, fica firme. Para uma referência objetiva, um termômetro de espeto resolve."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Depois de tirar do fogo, deixe a peça descansar de 5 a 10 minutos antes de cortar. Os sucos voltam para o centro e a carne fica mais macia. Corte sempre contra as fibras, em fatias de um dedo. Sirva aos poucos, e não tudo de uma vez: carne quente na tábua é o segredo do churrasco que a família lembra."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Os erros que arruínam a carne"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Carne gelada direto na grelha: tire da geladeira 30 minutos antes."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Virar toda hora: cada virada perde suco. Vire uma ou duas vezes."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Grelha suja: esfregue com escova e passe gordura antes de começar."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Fogo apressado com álcool: perigoso e deixa gosto na carne."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Cortar a carne na hora: espere o descanso."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Muita cerveja e pouca água: quem comanda a grelha precisa de atenção e do cansaço controlado."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Esse último ponto vale para a vida inteira do pai. A energia para passar horas em pé no calor vem do sono e do corpo em dia; o "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/treino-de-20-minutos-em-casa-para-pais-sem-tempo", "class": null, "rel": null, "target": null}}], "text": "treino de 20 minutos em casa"}, {"type": "text", "text": " e os "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/exames-que-todo-homem-deve-fazer-a-partir-dos-30-anos", "class": null, "rel": null, "target": null}}], "text": "exames que todo homem deve fazer a partir dos 30"}, {"type": "text", "text": " são parte do churrasco de domingo, mesmo que ninguém veja."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Crianças perto da churrasqueira"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Queimadura é o acidente mais comum do churrasco em família, e quase sempre acontece com criança pequena que corre perto da grelha. Defina uma área de brincar longe do fogo, combine com a esposa quem fica de olho enquanto você assa, e nunca deixe espeto quente apoiado na borda ao alcance de uma mão curiosa. Carvão apagado continua quente por horas; molhe bem antes de descartar."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Criança maior pode ajudar: buscar a tábua, levar o pão de alho, aprender a lavar a mão depois de pegar carne crua. É uma oportunidade de ensinar sem sermão, no mesmo espírito de "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/como-dar-limites-sem-gritar-autoridade-com-calma", "class": null, "rel": null, "target": null}}], "text": "como dar limites sem gritar"}, {"type": "text", "text": ": regra clara, tom firme, exemplo seu. Mais receitas e técnicas estão na seção "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/categoria/churrasco-e-cozinha", "class": null, "rel": null, "target": null}}], "text": "Churrasco e cozinha"}, {"type": "text", "text": "."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Semáforo do pai: churrasco em família"}]}, {"type": "callout", "attrs": {"tone": "ok"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sinal verde: brasa formada antes de a carne subir, carne com cor e cheiro bons, crianças em área definida com um adulto responsável, mãos lavadas depois da carne crua e sobras na geladeira em até duas horas."}]}]}, {"type": "callout", "attrs": {"tone": "warn"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sinal de atenção: carne que ficou mais de duas horas fora da geladeira no calor, frango com centro rosado, espeto ou grelha ao alcance das crianças, churrasqueira em área fechada sem ventilação ou carvão descartado ainda quente. Corrija antes de continuar."}]}]}, {"type": "callout", "attrs": {"tone": "bad"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sinal de alerta: queimadura com bolha, que atinja rosto, mão ou área grande, criança que tocou na grelha ou no carvão, dor de barriga forte com vômito e febre depois do churrasco, ou tontura e dor de cabeça perto de churrasqueira em ambiente fechado. Resfrie a queimadura com água corrente e procure o pronto-socorro; nas intoxicações e nos sintomas de fumaça, procure atendimento médico imediatamente."}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Tabela: os cortes para começar"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Corte"}]}]}, {"type": "tableHeader", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Fogo"}]}]}, {"type": "tableHeader", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tempo aproximado"}]}]}, {"type": "tableHeader", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Dica do pai"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Picanha em fatias grossas"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Forte, depois médio"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "4 a 6 min por lado"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Gordura para cima primeiro; sal grosso"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Fraldinha inteira"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Médio"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "20 a 30 min, virando 2 vezes"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Cortar contra as fibras"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Maminha inteira"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Médio"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "35 a 45 min"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Descansar 10 min antes de fatiar"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Costela bovina"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Baixo"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "3 a 5 horas"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Osso para baixo; paciência"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Linguiça toscana"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Médio"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "15 a 20 min"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Não furar; virar sempre"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Coxa e sobrecoxa de frango"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Médio para baixo"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "40 a 50 min"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Centro sem rosado"}]}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Os tempos variam com a espessura, o vento e a churrasqueira. Use a tabela como referência e confie no termômetro e no toque. Com três ou quatro churrascos você vai saber o ponto da sua grelha sem olhar relógio."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Checklist do pai: churrasco de domingo"}]}, {"type": "taskList", "content": [{"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Comprar 400 a 500 gramas por adulto e 200 por criança"}]}]}, {"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Acender o carvão 40 minutos antes, sem álcool líquido"}]}]}, {"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tirar a carne da geladeira 30 minutos antes"}]}]}, {"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Definir a área das crianças e quem fica de olho"}]}]}, {"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Deixar a carne descansar antes de cortar"}]}]}, {"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ficar atento aos sinais do semáforo acima"}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Churrasco é mais do que carne: é o pai no comando do fogo, a família em volta e a mesa cheia. Você não precisa acertar tudo no primeiro domingo. Precisa escolher bem, esperar a brasa, cuidar das crianças e servir com orgulho. O resto a prática ensina. Compre a carne, chame quem você ama e assuma a grelha."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Continue lendo: "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/kit-basico-de-ferramentas-para-a-casa", "class": null, "rel": null, "target": null}}], "text": "Kit básico de ferramentas para a casa: o que todo pai precisa ter"}, {"type": "text", "text": ", "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/treino-de-20-minutos-em-casa-para-pais-sem-tempo", "class": null, "rel": null, "target": null}}], "text": "Treino de 20 minutos em casa para pais sem tempo"}, {"type": "text", "text": ", "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/orcamento-familiar-para-quem-vai-ser-pai", "class": null, "rel": null, "target": null}}], "text": "Orçamento familiar para quem vai ser pai: passo a passo"}, {"type": "text", "text": ", "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/como-dar-limites-sem-gritar-autoridade-com-calma", "class": null, "rel": null, "target": null}}], "text": "Como dar limites sem gritar: autoridade com calma"}, {"type": "text", "text": ", "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/como-ser-um-marido-presente-depois-que-o-bebe-chega", "class": null, "rel": null, "target": null}}], "text": "Como ser um marido presente depois que o bebê chega"}, {"type": "text", "text": ", "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/vai-ser-pai-guia-do-primeiro-trimestre-para-o-homem", "class": null, "rel": null, "target": null}}], "text": "Vai ser pai: o guia do primeiro trimestre para o homem"}, {"type": "text", "text": " e "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/rotina-do-pai-nos-primeiros-30-dias-do-bebe", "class": null, "rel": null, "target": null}}], "text": "Rotina do pai nos primeiros 30 dias do bebê"}, {"type": "text", "text": "."}]}]}$body$::jsonb,
  $t$https://images.unsplash.com/photo-1534177616072-ef7dc120449d?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&q=80&w=1080$t$,
  $t$Homem de avental jeans virando a carne com uma espátula sobre a churrasqueira acesa no quintal$t$,
  (select id from public.categories where slug = $t$churrasco-e-cozinha$t$ and parent_id is null limit 1),
  (select id from public.profiles where display_name = 'Equipe Vocação de Pai' limit 1),
  'artigo',
  $faq$[{"question": "Quanto de carne compro por pessoa?", "answer": "Conte de 400 a 500 gramas de carne crua por adulto quando houver acompanhamentos (pão, vinagrete, arroz, farofa) e cerca de 200 gramas por criança. Se o churrasco for longo ou só de carne, suba para 600 gramas por adulto."}, {"question": "Sal grosso ou sal fino?", "answer": "Para cortes grossos, sal grosso na hora de ir para a grelha funciona bem e sai fácil na faca. Para cortes finos ou carne fatiada, o sal fino na hora de servir evita salgar demais. Teste os dois e escolha o seu padrão."}, {"question": "Posso congelar a carne que sobrou crua?", "answer": "Pode, desde que ela não tenha ficado fora da geladeira por muito tempo. Embale em porções, anote a data e consuma em até três meses. Carne que ficou horas no calor é melhor não guardar."}, {"question": "Qual corte é mais difícil de errar?", "answer": "A fraldinha e a maminha perdoam bastante: têm gordura entremeada, aceitam fogo médio e continuam macias mesmo se passarem um pouco do ponto. A picanha e a costela exigem mais atenção."}, {"question": "Churrasqueira elétrica serve para começar?", "answer": "Serve. Ela não dá o mesmo sabor de carvão, mas é segura, cabe em apartamento e permite treinar ponto e tempo. Quando você tiver a técnica, a brasa é um passo natural."}]$faq$::jsonb,
  $quiz$[{"question": "Qual é a quantidade razoável de carne crua por adulto, com acompanhamentos?", "options": ["150 gramas", "400 a 500 gramas", "1 quilo", "2 quilos"], "correct": 1, "explanation": "Com pão, vinagrete, farofa e arroz, 400 a 500 gramas por adulto costumam ser suficientes; crianças comem cerca de metade."}, {"question": "Por que a carne deve descansar alguns minutos depois de sair da grelha?", "options": ["Para esfriar completamente", "Para o suco se redistribuir e a carne ficar mais macia", "Para o sal evaporar", "Não precisa descansar"], "correct": 1, "explanation": "Descansar de 5 a 10 minutos permite que os sucos voltem ao centro da carne; cortar na hora deixa o suco todo na tábua."}, {"question": "Qual destes é um erro clássico do iniciante?", "options": ["Colocar a carne na grelha antes de a brasa estar formada", "Deixar a carne descansar", "Usar sal grosso em corte grosso", "Lavar as mãos depois de manusear carne crua"], "correct": 0, "explanation": "Carne em cima de chama viva queima por fora e fica crua por dentro; espere a brasa ficar cinza por cima."}, {"question": "Onde as crianças devem ficar durante o churrasco?", "options": ["Ao lado da churrasqueira, ajudando com os espetos", "Em uma área definida, longe do fogo, com um adulto de olho", "Em cima da bancada para ver melhor", "Perto do carvão aceso"], "correct": 1, "explanation": "Queimadura é o acidente mais comum do churrasco em família. Área definida e um adulto responsável resolvem a maior parte do risco."}]$quiz$::jsonb,
  'published',
  now(),
  9,
  $t$Cortes de carne para churrasco: guia do pai iniciante$t$,
  $t$Guia dos cortes de carne para churrasco: picanha, fraldinha, maminha e costela, quanto comprar por pessoa, como fazer o fogo e os erros a evitar.$t$
)
on conflict (slug) do nothing;

-- Treino de 20 minutos em casa para pais sem tempo
insert into public.posts (slug, title, subtitle, excerpt, body, cover_image_url, cover_image_alt, category_id, author_id, kind, faq, quiz, status, publish_at, reading_time, seo_title, seo_description)
values (
  $t$treino-de-20-minutos-em-casa-para-pais-sem-tempo$t$,
  $t$Treino de 20 minutos em casa para pais sem tempo$t$,
  $t$Seis exercícios com o peso do corpo, um plano de quatro semanas com progressão e o horário que funciona para quem tem filho pequeno e trabalho cheio.$t$,
  $t$Sem academia, sem equipamento, antes das crianças acordarem. Um plano de 4 semanas com progressão e tabela de exercícios.$t$,
  $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Você sabe que precisa se mexer. O médico falou, a esposa falou, a calça apertou. Mas entre o trabalho, o trânsito e as crianças, a academia virou um plano para o ano que vem. A verdade é que a maioria dos pais não precisa de duas horas de musculação: precisa de 20 minutos, quatro vezes por semana, em um horário que ninguém atrapalhe."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Este artigo entrega um plano de quatro semanas com seis exercícios que usam só o peso do corpo, uma tabela de progressão, o horário que funciona para quem tem filho pequeno e o Semáforo do Pai para você não se machucar. Antes de começar, se você não faz atividade física há anos, vale olhar os "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/exames-que-todo-homem-deve-fazer-a-partir-dos-30-anos", "class": null, "rel": null, "target": null}}], "text": "exames que todo homem deve fazer a partir dos 30"}, {"type": "text", "text": " e passar no médico: pressão e glicemia em dia tornam o treino mais seguro."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Por que 20 minutos bastam"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Treino curto e constante vence treino longo e abandonado. Vinte minutos de esforço real, sem celular e sem deslocamento, quatro vezes por semana, somam mais de 80 minutos de trabalho muscular. Para quem está parado, isso já melhora força, disposição, sono e humor nas primeiras semanas. O que não funciona é começar com uma hora, ficar dolorido por três dias e desistir na segunda semana."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Há também o efeito sobre a casa. Um pai com mais energia tem mais paciência para a birra das sete da noite, como mostramos em "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/como-dar-limites-sem-gritar-autoridade-com-calma", "class": null, "rel": null, "target": null}}], "text": "como dar limites sem gritar"}, {"type": "text", "text": ", e chega ao fim do dia com reserva para a esposa, não só cansaço. O treino não é um luxo seu; é parte do serviço que você presta à família."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Os seis exercícios do plano"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Tudo o que você precisa é um espaço de dois metros, uma cadeira firme e uma toalha ou tapete. Os exercícios são básicos de propósito: funcionam, têm progressão clara e não exigem técnica difícil."}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Agachamento: pés na largura dos ombros, desce como se fosse sentar, sobe pelos calcanhares. Trabalha pernas e glúteos."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Flexão de braço: comece com os joelhos no chão se precisar; evolua para a flexão completa. Trabalha peito, ombros e tríceps."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Afundo (passada): um pé à frente, desce o joelho de trás em direção ao chão, sobe. Alterne as pernas."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Remada na mesa: deite sob uma mesa firme, segure a borda e puxe o peito até ela. Trabalha as costas, o que a flexão não faz."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Prancha: antebraços no chão, corpo reto da cabeça ao calcanhar. Trabalha o abdômen e protege a coluna."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ponte de glúteo: deitado de costas, pés no chão, eleva o quadril. Fortalece a parte de trás do corpo e alivia a lombar de quem carrega criança no colo."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Esse último exercício importa mais do que parece. O pai que passa o dia erguendo um bebê de cinco quilos, como no passo a passo de "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/como-segurar-um-recem-nascido-com-seguranca", "class": null, "rel": null, "target": null}}], "text": "como segurar um recém-nascido com segurança"}, {"type": "text", "text": ", precisa de lombar e glúteo fortes. Sem isso, vem a dor nas costas que tanto pai de primeira viagem conhece."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O plano de 4 semanas com progressão"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "O formato é circuito: você faz os seis exercícios em sequência, descansa, e repete. Três minutos de aquecimento no começo (polichinelo leve, giro de braços, agachamento sem carga) e dois de alongamento no final. O tempo total fecha em 20 minutos. A progressão vem do número de rodadas e do tempo de trabalho, não de peso extra."}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Semana 1: 2 rodadas, 30 segundos de cada exercício, 30 segundos de descanso entre eles. Objetivo: aprender o movimento."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Semana 2: 3 rodadas, 30 segundos de trabalho, 20 de descanso. Objetivo: criar o hábito."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Semana 3: 3 rodadas, 40 segundos de trabalho, 20 de descanso. Objetivo: aumentar o esforço."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Semana 4: 4 rodadas, 40 segundos de trabalho, 15 de descanso. Objetivo: provar para você mesmo que dá."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Quatro treinos por semana, com um dia de intervalo entre eles, bastam. Terminada a quarta semana, você repete o ciclo subindo a dificuldade dos exercícios: flexão com os pés elevados, agachamento com salto, prancha com elevação de perna. Se preferir, troque um dos dias por uma caminhada rápida de 30 minutos com o carrinho do bebê."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Quando treinar: antes das crianças acordarem"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "O horário que mais funciona para pai de filho pequeno é o que ninguém disputa: 20 minutos antes de a casa acordar. Deixe a roupa separada na noite anterior, o tapete estendido na sala e o despertador 25 minutos mais cedo. Treinar de manhã também evita a armadilha da noite, quando o cansaço e o sofá ganham."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Se o bebê ainda não dorme a noite inteira, combine com a esposa: nos dias de treino, ela segura o primeiro despertar; nos outros, você. Isso faz parte da divisão de carga que descrevemos em "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/rotina-do-pai-nos-primeiros-30-dias-do-bebe", "class": null, "rel": null, "target": null}}], "text": "rotina do pai nos primeiros 30 dias do bebê"}, {"type": "text", "text": " e em "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/como-ser-um-marido-presente-depois-que-o-bebe-chega", "class": null, "rel": null, "target": null}}], "text": "como ser um marido presente depois que o bebê chega"}, {"type": "text", "text": ". Treino de um não pode virar sobrecarga do outro."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Como não se machucar"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Lesão de iniciante vem de três fontes: técnica ruim, pressa e falta de aquecimento. Faça cada movimento devagar na primeira semana e olhe sua postura em um espelho ou grave com o celular. Dor muscular leve no dia seguinte é esperada; dor aguda em joelho, ombro ou lombar durante o exercício é sinal de parar e revisar a técnica. Se a dor persistir, é hora do médico ou do fisioterapeuta, não de insistir."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Coma algo leve antes se for treinar logo ao acordar (uma banana, um pão) e beba água. Durma. Um pai que dorme cinco horas e treina forte está se desgastando, não se fortalecendo. O sono é o primeiro suplemento, e o mais barato do "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/orcamento-familiar-para-quem-vai-ser-pai", "class": null, "rel": null, "target": null}}], "text": "orçamento familiar"}, {"type": "text", "text": ". Outros temas de saúde estão na seção "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/categoria/corpo-e-saude-do-homem", "class": null, "rel": null, "target": null}}], "text": "Corpo e saúde do homem"}, {"type": "text", "text": "."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Treinar com os filhos por perto"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Criança gosta de imitar o pai. Se o seu filho acordar no meio do treino, convide-o para fazer agachamento junto, contar as flexões ou segurar o cronômetro. Vira brincadeira, e ele cresce vendo que cuidar do corpo é coisa de homem de família. Só evite exercícios com salto perto de bebê engatinhando e mantenha a cadeira usada no afundo bem firme."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Com o tempo, esse treino de sala pode virar futebol no quintal, bicicleta no domingo e, mais à frente, o filho adolescente querendo treinar com você. Começa com 20 minutos; termina em legado. E se a esposa está grávida, como no "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/vai-ser-pai-guia-do-primeiro-trimestre-para-o-homem", "class": null, "rel": null, "target": null}}], "text": "guia do primeiro trimestre para o homem"}, {"type": "text", "text": ", este é o melhor momento para começar: você vai precisar do fôlego."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Semáforo do pai: dor e sinais do corpo"}]}, {"type": "callout", "attrs": {"tone": "ok"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sinal verde: dor muscular leve no dia seguinte, suor, respiração acelerada que volta ao normal em poucos minutos e cansaço bom. É o corpo se adaptando; mantenha o plano."}]}]}, {"type": "callout", "attrs": {"tone": "warn"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sinal de atenção: dor que dura mais de três dias, dor em articulação (joelho, ombro, punho), tontura leve durante o treino ou cansaço que piora ao longo da semana. Reduza o volume, revise a técnica e o sono, e converse com um profissional de educação física ou fisioterapeuta."}]}]}, {"type": "callout", "attrs": {"tone": "bad"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sinal de alerta: dor ou aperto no peito durante o esforço, falta de ar desproporcional, desmaio, dor aguda que trava uma articulação ou inchaço que não diminui. Pare imediatamente e procure um médico ou pronto-socorro antes de qualquer novo treino."}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Tabela: as 4 semanas do plano"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Semana"}]}]}, {"type": "tableHeader", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Rodadas"}]}]}, {"type": "tableHeader", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Trabalho por exercício"}]}]}, {"type": "tableHeader", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Descanso"}]}]}, {"type": "tableHeader", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Foco"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "1"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "2"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "30 segundos"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "30 segundos"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Aprender o movimento"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "2"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "3"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "30 segundos"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "20 segundos"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Criar o hábito"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "3"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "3"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "40 segundos"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "20 segundos"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Aumentar o esforço"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "4"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "4"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "40 segundos"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "15 segundos"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Consolidar e progredir"}]}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Ao terminar as quatro semanas, anote quantas repetições fez em cada exercício na última rodada. Esse número é a sua marca; na próxima rodada do ciclo, a meta é superá-la. Fazer churrasco com energia no domingo, como no "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/cortes-de-carne-para-churrasco-guia-do-pai-iniciante", "class": null, "rel": null, "target": null}}], "text": "guia de cortes para o pai iniciante"}, {"type": "text", "text": ", é parte da recompensa, e montar um suporte de parede para a barra com as ferramentas do "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/kit-basico-de-ferramentas-para-a-casa", "class": null, "rel": null, "target": null}}], "text": "kit básico"}, {"type": "text", "text": " é o próximo projeto."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Checklist do pai: treino de 20 minutos"}]}, {"type": "taskList", "content": [{"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Passar no médico se estiver parado há anos"}]}]}, {"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Separar roupa e tapete na noite anterior"}]}]}, {"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Acordar 25 minutos antes da casa"}]}]}, {"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Fazer 3 minutos de aquecimento e 2 de alongamento"}]}]}, {"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Anotar rodadas e repetições a cada semana"}]}]}, {"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ficar atento aos sinais do semáforo acima"}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Você não precisa de academia, de tempo sobrando nem de motivação de filme. Precisa de 20 minutos e de uma decisão repetida quatro vezes por semana. Em um mês, você vai subir a escada com o filho no colo sem perder o fôlego e vai dormir melhor. Comece amanhã de manhã. Seus filhos merecem um pai forte, e você merece se sentir um."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Continue lendo: "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/exames-que-todo-homem-deve-fazer-a-partir-dos-30-anos", "class": null, "rel": null, "target": null}}], "text": "Exames que todo homem deve fazer a partir dos 30 anos"}, {"type": "text", "text": ", "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/rotina-do-pai-nos-primeiros-30-dias-do-bebe", "class": null, "rel": null, "target": null}}], "text": "Rotina do pai nos primeiros 30 dias do bebê"}, {"type": "text", "text": ", "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/como-ser-um-marido-presente-depois-que-o-bebe-chega", "class": null, "rel": null, "target": null}}], "text": "Como ser um marido presente depois que o bebê chega"}, {"type": "text", "text": ", "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/como-segurar-um-recem-nascido-com-seguranca", "class": null, "rel": null, "target": null}}], "text": "Como segurar um recém-nascido com segurança (e sem medo)"}, {"type": "text", "text": " e "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/cortes-de-carne-para-churrasco-guia-do-pai-iniciante", "class": null, "rel": null, "target": null}}], "text": "Cortes de carne para churrasco: guia do pai iniciante"}, {"type": "text", "text": "."}]}]}$body$::jsonb,
  $t$https://images.unsplash.com/photo-1760084081757-6f918c08403b?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&q=80&w=1080$t$,
  $t$Homem sorrindo enquanto faz flexão de braço sobre o tapete da sala de casa, com a luz da manhã entrando pela janela$t$,
  (select id from public.categories where slug = $t$corpo-e-saude-do-homem$t$ and parent_id is null limit 1),
  (select id from public.profiles where display_name = 'Equipe Vocação de Pai' limit 1),
  'artigo',
  $faq$[{"question": "Vinte minutos por dia fazem diferença mesmo?", "answer": "Fazem, desde que sejam constantes. Quatro sessões de 20 minutos por semana somam mais de uma hora de esforço real, sem contar deslocamento. Para quem não treina há anos, é o suficiente para ganhar força, disposição e sono melhor nas primeiras semanas."}, {"question": "Preciso de algum equipamento?", "answer": "Não. O plano usa só o peso do corpo, uma cadeira firme e um tapete ou toalha. Se quiser evoluir depois, uma barra de porta e um par de halteres ajudam, mas não são obrigatórios."}, {"question": "Posso treinar com o bebê no quarto?", "answer": "Pode, desde que o espaço seja seguro e você consiga ver a criança o tempo todo. Muitos pais treinam na sala enquanto o bebê fica no tapete de atividades ao lado. Evite exercícios com salto perto da criança."}, {"question": "E se eu sentir dor durante o exercício?", "answer": "Dor aguda, que fisga ou trava, é sinal para parar na hora. Desconforto muscular leve, do esforço, é normal. Se a dor continuar nos dias seguintes ou aparecer em articulação, procure um médico ou fisioterapeuta antes de voltar."}, {"question": "Quando vou começar a ver resultado?", "answer": "A disposição e o sono costumam melhorar nas duas primeiras semanas. Força visível, de fazer mais repetições com menos esforço, aparece por volta da quarta semana. Mudança no corpo leva mais tempo e depende também da alimentação."}]$faq$::jsonb,
  $quiz$[{"question": "Qual é o maior erro de quem começa a treinar em casa?", "options": ["Treinar em jejum", "Querer fazer tudo no primeiro dia e desistir na segunda semana", "Treinar na sala", "Fazer agachamento"], "correct": 1, "explanation": "Constância vence intensidade. Começar com menos e repetir toda semana é o que mantém o hábito."}, {"question": "O que fazer se sentir dor aguda em uma articulação durante o treino?", "options": ["Continuar até passar", "Trocar para um exercício mais pesado", "Parar na hora e, se persistir, buscar um profissional", "Tomar analgésico e seguir"], "correct": 2, "explanation": "Dor que fisga ou trava é sinal de parar. Se persistir, médico ou fisioterapeuta avaliam antes de você voltar."}, {"question": "Qual destes exercícios trabalha principalmente as pernas?", "options": ["Flexão de braço", "Prancha", "Agachamento", "Remada na mesa"], "correct": 2, "explanation": "O agachamento é o exercício básico de perna e glúteo, e dá para progredir só com o peso do corpo."}, {"question": "Por que aquecer antes do treino?", "options": ["Para gastar tempo", "Para preparar músculos e articulações e reduzir o risco de lesão", "Para suar mais", "Não é necessário"], "correct": 1, "explanation": "Três minutos de aquecimento elevam a temperatura muscular e preparam as articulações para o esforço."}]$quiz$::jsonb,
  'published',
  now(),
  8,
  $t$Treino de 20 minutos em casa para pais sem tempo$t$,
  $t$Plano de treino de 20 minutos em casa, sem equipamento, para pais sem tempo: 6 exercícios, 4 semanas de progressão, tabela e sinais de alerta.$t$
)
