-- Como ser um marido presente depois que o bebê chega
insert into public.posts (slug, title, subtitle, excerpt, body, cover_image_url, cover_image_alt, category_id, author_id, kind, faq, quiz, status, publish_at, reading_time, seo_title, seo_description)
values (
  $t$como-ser-um-marido-presente-depois-que-o-bebe-chega$t$,
  $t$Como ser um marido presente depois que o bebê chega$t$,
  $t$O filho nasce e o casamento muda. Como cuidar da esposa no pós-parto, dividir a carga, preservar a intimidade e liderar a casa servindo.$t$,
  $t$O casamento muda quando o filho nasce. Como cuidar da esposa, manter a intimidade, dividir a carga e liderar a casa com serviço.$t$,
  $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "O bebê chegou, a casa virou um pronto-socorro de fraldas e mamadas, e você, que era o marido, virou o cara que busca as coisas. A esposa chora sem motivo aparente, dorme de duas em duas horas e parece não ter mais espaço para você. É nessa hora que muito homem se encolhe, foge para o trabalho ou para o celular, e o casamento começa a esfriar sem ninguém perceber."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Este artigo mostra o que muda de verdade no casamento quando o filho nasce, como cuidar da esposa nas semanas do pós-parto, como dividir a carga sem planilha de culpa, como a intimidade volta e como liderar a casa servindo. É a continuação natural da "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/rotina-do-pai-nos-primeiros-30-dias-do-bebe", "class": null, "rel": null, "target": null}}], "text": "rotina do pai nos primeiros 30 dias do bebê"}, {"type": "text", "text": ": lá está o que fazer com o bebê; aqui, o que fazer com o casamento."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que muda no casamento quando o filho nasce"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Três coisas mudam ao mesmo tempo: o sono, o tempo a dois e o lugar de cada um. Antes, vocês eram marido e mulher; agora são também pai e mãe, e a primeira identidade precisa ser cuidada para não sumir atrás da segunda. A esposa passa semanas em recuperação física e hormonal; você passa a ser o adulto mais descansado da casa, o que significa que a carga pesada é sua."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Não é injustiça, é ordem. O homem que entende isso cedo poupa anos de ressentimento. O que sustenta o casal nessa fase não é romantismo, é serviço: louça lavada, visita controlada, noite dividida, uma palavra de reconhecimento por dia. O jeito firme e calmo que você vai usar com os filhos daqui a alguns anos, descrito em "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/como-dar-limites-sem-gritar-autoridade-com-calma", "class": null, "rel": null, "target": null}}], "text": "como dar limites sem gritar"}, {"type": "text", "text": ", começa com a calma que você oferece à esposa agora."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Cuidar da esposa é cuidar da família"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "O pós-parto não termina na alta da maternidade. Ela está com o corpo em reparo, pode ter pontos, dor ao amamentar, sangramento por semanas e uma queda hormonal que mexe com o humor. O que ela precisa de você é concreto: água e comida ao alcance enquanto amamenta, banho tranquilo sem o bebê chorando, duas horas de sono seguidas pelo menos uma vez ao dia, e a garantia de que você está de olho no bebê quando ela fecha os olhos."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Observe o humor dela, mas sem vigilância. Choro fácil e sensibilidade nos primeiros dez a quinze dias são esperados e passam com descanso e apoio. Se não passarem, se piorarem, ou se ela demonstrar desinteresse pelo bebê, desesperança ou medo constante, o marido presente não espera: liga para o obstetra. Depressão pós-parto é condição médica, tem tratamento, e quem mais ajuda a identificar é o homem que está em casa. Enquanto cuida dela, não esqueça de você: os "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/exames-que-todo-homem-deve-fazer-a-partir-dos-30-anos", "class": null, "rel": null, "target": null}}], "text": "exames que todo homem deve fazer a partir dos 30"}, {"type": "text", "text": " incluem o seu sono e o seu humor."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Dividir a carga sem planilha de culpa"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Esqueça a ideia de dividir meio a meio. Nas primeiras semanas a divisão é desigual de propósito: ela amamenta e se recupera; você faz o resto. O resto inclui trocar fraldas, dar banho, carregar o bebê no colo para ela comer sentada, lavar louça, estender roupa, receber visitas, fazer compras e organizar a casa. Se não sabe por onde começar, o passo a passo de "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/como-segurar-um-recem-nascido-com-seguranca", "class": null, "rel": null, "target": null}}], "text": "como segurar um recém-nascido com segurança"}, {"type": "text", "text": " tira o medo da primeira tarefa."}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Noite: combine turnos. Se ela amamenta, você busca o bebê, troca a fralda e devolve para a cama; ela só amamenta."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Comida: uma refeição quente por dia é responsabilidade sua, mesmo que seja simples."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Casa: o que você fazia antes, continua; o que ela fazia, você assume por algumas semanas."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Visitas: você é o porteiro. Horário, duração e lista de quem entra são decisão do casal, comunicada por você."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Trabalho: use a licença-paternidade inteira e negocie flexibilidade com o chefe antes do parto, se possível."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A conta fecha quando ela recupera o corpo e o sono. Aí, sim, a divisão se reorganiza. O que não pode acontecer é você fazer tudo com cara de sacrifício, cobrando reconhecimento. Serviço com mau humor não é serviço."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Intimidade: paciência, carinho e conversa"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A intimidade do casal depois do parto volta em camadas. Primeiro vem o toque sem intenção: mão no ombro, abraço demorado, carinho no cabelo enquanto ela amamenta. Depois vem a conversa de verdade, dez minutos por dia sem bebê no assunto. A relação conjugal propriamente dita só depois da liberação médica, em geral no retorno de 40 dias, e no tempo dela, que pode ser mais longo por cansaço e hormônios."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Cobrar não ajuda, e comparar com antes também não. O marido que cuida, espera e conversa cria o ambiente em que o desejo volta; o que cobra e se afasta cria o oposto. Se a dificuldade persistir por meses, o casal pode conversar com o obstetra ou com um orientador conjugal de confiança. Fale com ela sobre isso com respeito, como fala de qualquer outro assunto importante da casa."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Visitas, sogros e a palavra final do casal"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Todo mundo quer ver o bebê, e todo mundo tem opinião. A sua função é proteger o descanso da esposa e a intimidade da casa. Defina com ela, antes do parto, o que vale: horário de visitas, se avós dormem na casa ou não, quem pode pegar o bebê. Depois, comunique você, com educação e firmeza. Ela não deve ter de brigar com a sogra; você conversa com a sua mãe, ela conversa com a dela."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Ajuda de confiança é bem-vinda, e não é fraqueza aceitar: a mãe dela cozinhando por uma semana vale ouro. O que precisa ficar claro é que a casa tem um casal no comando, e que as decisões sobre o bebê são de vocês dois. O mesmo princípio vale para o dinheiro, que agora tem novas despesas, como mostra o "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/orcamento-familiar-para-quem-vai-ser-pai", "class": null, "rel": null, "target": null}}], "text": "orçamento familiar para quem vai ser pai"}, {"type": "text", "text": ": decisão a dois, comunicada por quem lidera."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Fé a dois: a oração curta no fim do dia"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "No meio do caos, uma coisa segura o casal: dois minutos de oração juntos antes de dormir. Um Pai-Nosso, uma Ave-Maria, um pedido de proteção para o bebê e um agradecimento pelo dia. Não precisa ser longo nem bonito; precisa ser todo dia. Casais que rezam juntos conversam mais, perdoam mais rápido e lembram que a família tem um dono maior que os dois. São José, que cuidou de Maria e do Menino sem dizer uma palavra registrada, é o patrono do marido presente: trabalho, silêncio e proteção."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Se a sua esposa ainda está grávida, comece agora. O "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/vai-ser-pai-guia-do-primeiro-trimestre-para-o-homem", "class": null, "rel": null, "target": null}}], "text": "guia do primeiro trimestre para o homem"}, {"type": "text", "text": " explica como acompanhar a gestação; a oração de casal é o hábito que atravessa a gravidez, o parto e os anos seguintes. Outros temas de vida a dois estão na seção "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/categoria/casamento-e-familia", "class": null, "rel": null, "target": null}}], "text": "Casamento e família"}, {"type": "text", "text": "."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Semáforo do pai: a esposa no pós-parto"}]}, {"type": "callout", "attrs": {"tone": "ok"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sinal verde: ela chora às vezes, cansa fácil e tem dias difíceis, mas aceita ajuda, cuida do bebê com carinho, dorme quando pode e vai melhorando ao longo das duas primeiras semanas. Mantenha o apoio e a rotina de descanso."}]}]}, {"type": "callout", "attrs": {"tone": "warn"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sinal de atenção: tristeza ou irritação que não melhora depois de duas semanas, sono impossível mesmo quando o bebê dorme, falta de apetite, choro frequente, sensação de não dar conta ou afastamento do bebê. Converse com ela sem julgar e marque uma consulta com o obstetra ou o médico de família."}]}]}, {"type": "callout", "attrs": {"tone": "bad"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sinal de alerta: desesperança profunda, falas de que o bebê ou a família estariam melhor sem ela, confusão mental, medo de machucar o bebê, febre alta, sangramento intenso ou dor forte que não cede. Não espere o retorno de 40 dias: leve-a ao pronto atendimento ou ligue para o obstetra agora; em sofrimento emocional grave, o CVV atende pelo 188 e um psiquiatra deve avaliar."}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Tabela: o que ela precisa e o que você faz"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Situação"}]}]}, {"type": "tableHeader", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "O que ela precisa"}]}]}, {"type": "tableHeader", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "O que você faz"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Amamentação"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Água, comida e silêncio"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Deixa copo e lanche ao lado, cuida do telefone e das visitas"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Noite"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Blocos de sono"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Busca, troca e devolve o bebê; assume a primeira hora da manhã"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Humor instável"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Escuta e paciência"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Pergunta, ouve, não corrige; observa os sinais do semáforo"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Visitas"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Controle do próprio espaço"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Define horário e duração e comunica à família"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Intimidade"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tempo e carinho sem cobrança"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Toque, conversa diária e espera pela liberação médica"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Casa"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Não se sentir sozinha na tarefa"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Louça, roupa, compras e uma refeição quente por dia"}]}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Leia a tabela com ela. Muitas brigas do primeiro ano vêm de expectativa não dita: ela espera que você perceba, você espera que ela peça. Colocar no papel o que cada um faz nas primeiras semanas resolve metade do problema antes de ele existir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Checklist do pai: marido presente"}]}, {"type": "taskList", "content": [{"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Usar a licença-paternidade inteira"}]}]}, {"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Garantir à esposa um bloco de sono por dia"}]}]}, {"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Assumir a louça, a roupa e uma refeição quente"}]}]}, {"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ser o porteiro das visitas e dos sogros"}]}]}, {"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Rezar dois minutos com ela antes de dormir"}]}]}, {"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ficar atento aos sinais do semáforo acima"}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "O homem que a sua esposa escolheu não desaparece quando o filho nasce; ele cresce. Presença não é estar na mesma casa, é carregar o peso que ela não consegue carregar agora e fazer isso com alegria. O bebê vai crescer e esquecer essas semanas, mas ela não. Seja o marido de que ela vai lembrar com gratidão: o que ficou, serviu e protegeu."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Continue lendo: "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/rotina-do-pai-nos-primeiros-30-dias-do-bebe", "class": null, "rel": null, "target": null}}], "text": "Rotina do pai nos primeiros 30 dias do bebê"}, {"type": "text", "text": ", "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/como-segurar-um-recem-nascido-com-seguranca", "class": null, "rel": null, "target": null}}], "text": "Como segurar um recém-nascido com segurança (e sem medo)"}, {"type": "text", "text": ", "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/vai-ser-pai-guia-do-primeiro-trimestre-para-o-homem", "class": null, "rel": null, "target": null}}], "text": "Vai ser pai: o guia do primeiro trimestre para o homem"}, {"type": "text", "text": ", "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/orcamento-familiar-para-quem-vai-ser-pai", "class": null, "rel": null, "target": null}}], "text": "Orçamento familiar para quem vai ser pai: passo a passo"}, {"type": "text", "text": ", "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/treino-de-20-minutos-em-casa-para-pais-sem-tempo", "class": null, "rel": null, "target": null}}], "text": "Treino de 20 minutos em casa para pais sem tempo"}, {"type": "text", "text": ", "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/cortes-de-carne-para-churrasco-guia-do-pai-iniciante", "class": null, "rel": null, "target": null}}], "text": "Cortes de carne para churrasco: guia do pai iniciante"}, {"type": "text", "text": " e "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/kit-basico-de-ferramentas-para-a-casa", "class": null, "rel": null, "target": null}}], "text": "Kit básico de ferramentas para a casa: o que todo pai precisa ter"}, {"type": "text", "text": "."}]}]}$body$::jsonb,
  $t$https://images.unsplash.com/photo-1758698856229-6f3dfd08fcc7?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&q=80&w=1080$t$,
  $t$Pai e mãe abraçados segurando o bebê recém-nascido que dorme no colo da mãe$t$,
  (select id from public.categories where slug = $t$casamento-e-familia$t$ and parent_id is null limit 1),
  (select id from public.profiles where display_name = 'Equipe Vocação de Pai' limit 1),
  'artigo',
  $faq$[{"question": "Minha esposa chora muito depois do parto. É normal?", "answer": "Nos primeiros dez a quinze dias, choro fácil, sensibilidade e cansaço são comuns e costumam passar com descanso e apoio. Se durar mais do que isso, piorar ou vier com desinteresse pelo bebê e desesperança, é hora de ligar para o obstetra: pode ser depressão pós-parto, que tem tratamento."}, {"question": "Quando a intimidade volta depois do parto?", "answer": "O corpo dela precisa de liberação médica, geralmente no retorno de 40 dias, e o desejo pode levar mais tempo, por cansaço e hormônios. Carinho, conversa e paciência vêm antes. Não cobre; cuide."}, {"question": "Como lidar com sogros que opinam demais?", "answer": "Com respeito e clareza. Agradeça a ajuda, defina com a esposa as regras da casa e seja você a comunicar as decisões do casal, com educação. Ela precisa saber que o marido a protege, inclusive da própria família."}, {"question": "E se eu estiver exausto também?", "answer": "Você vai estar. Durma quando o bebê dorme nos primeiros dias, aceite ajuda de confiança, mantenha uma refeição decente por dia e um pouco de ar livre. Se o cansaço virar desânimo profundo ou irritação constante, converse com um médico: pai também adoece."}, {"question": "Vale a pena marcar um tempo só para o casal?", "answer": "Vale, mesmo que seja meia hora no sofá depois de o bebê dormir. Casal que conversa dez minutos por dia atravessa o primeiro ano com mais força. Uma oração curta a dois no fim do dia é um jeito simples de começar."}]$faq$::jsonb,
  $quiz$[{"question": "Qual é o período em que choro fácil e sensibilidade costumam ser esperados no pós-parto?", "options": ["Os primeiros dez a quinze dias", "O primeiro ano inteiro", "Só no dia do parto", "Nunca é esperado"], "correct": 0, "explanation": "O chamado baby blues costuma durar até duas semanas; se passar disso ou piorar, é caso de avaliação médica."}, {"question": "O que significa liderar a casa servindo, nas primeiras semanas?", "options": ["Dar ordens sobre o cuidado do bebê", "Assumir as tarefas que ninguém quer e proteger o descanso da esposa", "Deixar tudo com a mãe porque ela entende mais", "Sair mais para descansar"], "correct": 1, "explanation": "Liderança servidora é a de quem chega primeiro no trabalho pesado: fralda, louça, noite, visitas."}, {"question": "Como lidar com a intimidade conjugal depois do parto?", "options": ["Cobrar o retorno rápido", "Esperar a liberação médica e cuidar do carinho e da conversa antes", "Evitar o assunto para sempre", "Deixar que ela resolva sozinha"], "correct": 1, "explanation": "A liberação médica vem no retorno de 40 dias; o desejo pode levar mais tempo. Carinho e paciência reconstroem a intimidade."}, {"question": "O que fazer se a esposa demonstra desinteresse pelo bebê e desesperança por mais de duas semanas?", "options": ["Esperar passar", "Dizer que ela precisa ser forte", "Ligar para o obstetra e buscar avaliação médica", "Chamar a sogra para resolver"], "correct": 2, "explanation": "Esses sinais podem indicar depressão pós-parto, condição médica que tem tratamento e precisa de avaliação profissional."}]$quiz$::jsonb,
  'published',
  now(),
  9,
  $t$Como ser um marido presente depois que o bebê chega$t$,
  $t$O casamento muda com o filho. Veja como cuidar da esposa no pós-parto, dividir a carga, manter a intimidade e liderar a casa servindo.$t$
)
on conflict (slug) do nothing;

-- Kit básico de ferramentas para a casa: o que todo pai precisa ter
insert into public.posts (slug, title, subtitle, excerpt, body, cover_image_url, cover_image_alt, category_id, author_id, kind, faq, quiz, status, publish_at, reading_time, seo_title, seo_description)
values (
  $t$kit-basico-de-ferramentas-para-a-casa$t$,
  $t$Kit básico de ferramentas para a casa: o que todo pai precisa ter$t$,
  $t$As 15 ferramentas que resolvem a maior parte dos consertos da casa, a ordem certa de compra, como escolher sem desperdício e quando chamar o profissional.$t$,
  $t$As 15 ferramentas essenciais, o que comprar primeiro, como escolher cada uma e os 10 consertos que você passa a resolver sozinho.$t$,
  $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A torneira pinga, a porta do armário está caída, o quadro da sala ainda não subiu na parede e a sua esposa já pediu três vezes. Você quer resolver, mas abre a gaveta e encontra uma chave de fenda com a ponta gasta e um martelo emprestado do vizinho. Para o pai que quer cuidar da própria casa, a falta de ferramenta certa vira desculpa, e a desculpa vira conta de profissional por coisa simples."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Este artigo lista as 15 ferramentas que resolvem a maior parte dos consertos domésticos, mostra a ordem certa de compra, explica como escolher cada uma sem desperdício, entrega os 10 consertos que você passa a fazer sozinho e marca, no Semáforo do Pai, quando é hora de chamar o eletricista ou o encanador. É um investimento que cabe no "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/orcamento-familiar-para-quem-vai-ser-pai", "class": null, "rel": null, "target": null}}], "text": "orçamento familiar"}, {"type": "text", "text": " e se paga no primeiro conserto evitado."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "As 15 ferramentas essenciais"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Você não precisa de oficina. Precisa de uma maleta com estas peças, escolhidas pela frequência com que aparecem nos consertos de uma casa com crianças:"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Jogo de chaves de fenda e Phillips em três tamanhos, com cabo emborrachado."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Martelo de unha de 500 gramas, para pregar e arrancar prego."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Trena de 5 metros com trava."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Alicate universal, para cortar, segurar e dobrar arame."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Alicate de bico, para espaços apertados e peças pequenas."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Chave inglesa ajustável, para porcas de torneira e de válvula."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Jogo de chaves allen, obrigatório para móvel desmontável e bicicleta das crianças."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Nível de bolha de 30 a 40 centímetros."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Estilete com lâmina retrátil e lâminas de reposição."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Serrote pequeno ou serra de arco, para madeira e cano de PVC."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Parafusadeira-furadeira sem fio com jogo de brocas para madeira, metal e alvenaria."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Chave de teste de tensão, para confirmar que a tomada está sem energia."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Fita isolante, fita veda-rosca e fita crepe."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Caixa de buchas e parafusos sortidos, com pregos pequenos."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Lanterna de cabeça, para mexer embaixo da pia e no forro sem segurar luz."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Some a isso óculos de proteção e luvas. Parece exagero até a primeira lasca de madeira no olho. Quem já tem o "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/treino-de-20-minutos-em-casa-para-pais-sem-tempo", "class": null, "rel": null, "target": null}}], "text": "treino de 20 minutos"}, {"type": "text", "text": " na rotina sabe que a lógica é a mesma: equipamento simples, usado com constância, resolve muito mais do que equipamento caro parado."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que comprar primeiro"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Se o dinheiro é curto, compre em três etapas. A primeira, a base manual: chaves de fenda e Phillips, martelo, trena, alicate universal e fita isolante. Com isso você já aperta dobradiça, troca pé de cadeira, pendura quadro leve e resolve pequenas emergências. A segunda etapa acrescenta chave inglesa, allen, nível, estilete e veda-rosca, o que abre a porta das torneiras e dos móveis. A terceira é a parafusadeira com brocas, que transforma o pai em instalador de prateleira, cortina, suporte de TV e cadeirinha de parede."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Comprar um kit pronto de marca conhecida costuma sair mais barato do que peça por peça, desde que você fuja dos kits de 200 peças de qualidade duvidosa. Menos itens e melhores. Ferramenta boa dura décadas e passa para o filho; a ruim quebra no segundo parafuso e ainda machuca. A conta é a mesma do churrasco: um corte bom vale mais do que três medianos, como no "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/cortes-de-carne-para-churrasco-guia-do-pai-iniciante", "class": null, "rel": null, "target": null}}], "text": "guia de cortes para o pai iniciante"}, {"type": "text", "text": "."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Como escolher sem desperdício"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Cabo emborrachado e peso equilibrado na mão: ferramenta que escorrega vira acidente."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Aço com acabamento cromado nas chaves e alicates: resiste à ferrugem do banheiro e da área de serviço."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Parafusadeira entre 12 e 20 volts, com duas baterias se possível: uma carrega enquanto a outra trabalha."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Trena com fita larga, que não dobra quando esticada sozinho."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Marcas com assistência técnica no Brasil, para repor bateria e peça."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Pesquise a faixa de preço em duas ou três lojas antes de comprar; a diferença entre lojas no mesmo item costuma ser grande."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Nos próximos meses, a Loja do Pai vai reunir reviews e comparativos de ferramentas com faixa de preço pesquisada, para você não comprar no escuro. Até lá, a regra é simples: leia a avaliação de quem usou, prefira marca com reposição de peças e compre a ferramenta para o trabalho que você faz, não para o que imagina fazer um dia."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Os 10 consertos que você passa a resolver sozinho"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Com a maleta completa e meia hora de paciência, estes consertos deixam de ser chamada de profissional:"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Trocar o reparo ou a vedação da torneira que pinga, com a chave inglesa e o veda-rosca."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ajustar dobradiça de porta de armário caída, apertando ou trocando os parafusos."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Pendurar quadro, prateleira e suporte de TV com bucha certa, nível e parafusadeira."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Trocar tomada ou interruptor queimado, com o disjuntor desligado e a chave de teste confirmando."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Montar e reapertar móveis desmontáveis, berço e cadeira de alimentação com o jogo allen."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Desentupir sifão da pia desmontando o copo com a mão e a chave inglesa."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Trocar a resistência do chuveiro, com a energia desligada no disjuntor."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Instalar protetor de tomada, trava de armário e grade de proteção para o bebê que começa a andar."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Reparar porta que arrasta, ajustando as dobradiças ou aplainando a borda com lixa."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Consertar o pé da cadeira ou da mesa bambo com cola de madeira e parafuso novo."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "O item oito merece destaque. Quando o bebê começa a engatinhar, a casa precisa de protetores e travas em uma tarde, e o pai que domina a parafusadeira faz isso antes de o filho descobrir a tomada. É a mesma prontidão de "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/como-segurar-um-recem-nascido-com-seguranca", "class": null, "rel": null, "target": null}}], "text": "como segurar um recém-nascido com segurança"}, {"type": "text", "text": ": aprender antes de precisar. Se a esposa ainda está grávida, montar o berço e o trocador com as próprias mãos é um dos melhores usos do "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/vai-ser-pai-guia-do-primeiro-trimestre-para-o-homem", "class": null, "rel": null, "target": null}}], "text": "primeiro trimestre"}, {"type": "text", "text": "."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Onde guardar e como manter"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Ferramenta guardada em lugar fixo é ferramenta que existe na hora do aperto. Uma maleta com trava ou um armário alto na área de serviço resolve. Estilete, serra, lâminas e produtos químicos ficam trancados, sempre. Depois de cada uso, limpe, seque e devolva ao lugar; uma vez por mês, passe um pano com óleo fino nas partes metálicas e carregue as baterias. Ferramenta enferrujada é dinheiro jogado fora."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Com o filho maior, a maleta vira escola: ele segura a lanterna, aprende o nome das peças, aperta o primeiro parafuso com a sua mão por cima. É tempo de qualidade que ensina responsabilidade sem sermão, no espírito de "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/como-dar-limites-sem-gritar-autoridade-com-calma", "class": null, "rel": null, "target": null}}], "text": "como dar limites sem gritar"}, {"type": "text", "text": ": regra clara, tom firme, exemplo. Mais projetos passo a passo estão na seção "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/categoria/caixa-de-ferramentas-e-reparos", "class": null, "rel": null, "target": null}}], "text": "Caixa de ferramentas e reparos"}, {"type": "text", "text": "."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Segurança: elétrica, altura e crianças"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Três regras não se negociam. Primeira: antes de tocar em qualquer fio, desligue o disjuntor do circuito e confirme com a chave de teste; não confie no interruptor. Segunda: escada firme, nunca cadeira ou banco, e alguém segurando quando passar de dois degraus. Terceira: criança pequena fora do ambiente durante o conserto, e ferramenta recolhida antes de ela voltar. Óculos de proteção para furar, lixar e cortar."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Também vale saber o seu limite. Quadro de distribuição, fiação nova, gás, chuveiro que desarma o disjuntor, vazamento dentro da parede e qualquer trabalho em altura externa são serviço de profissional. O pai que chama o eletricista na hora certa está protegendo a família, exatamente como o que marca os "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/exames-que-todo-homem-deve-fazer-a-partir-dos-30-anos", "class": null, "rel": null, "target": null}}], "text": "exames a partir dos 30 anos"}, {"type": "text", "text": " em vez de esperar o problema aparecer."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Semáforo do pai: reparos em casa"}]}, {"type": "callout", "attrs": {"tone": "ok"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sinal verde: conserto simples (torneira, dobradiça, quadro, móvel, tomada com disjuntor desligado e testado), ferramenta certa em mãos, crianças fora do ambiente, escada firme e você sem pressa. Pode fazer."}]}]}, {"type": "callout", "attrs": {"tone": "warn"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sinal de atenção: cheiro de queimado em tomada, torneira que continua pingando depois do reparo, parede que fica úmida sem motivo visível, parafuso que não firma na bucha ou um trabalho que exige escada acima de dois degraus sem ninguém para segurar. Pare, reavalie e considere chamar um profissional."}]}]}, {"type": "callout", "attrs": {"tone": "bad"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sinal de alerta: disjuntor que desarma repetidamente, fio aquecendo, choque ao tocar em torneira ou chuveiro, cheiro de gás, vazamento de água dentro da parede ou no teto, ou qualquer corte e queimadura com ferramenta que não para de sangrar ou atinge o olho. Desligue a energia ou o registro, afaste a família e procure um eletricista, um encanador ou o pronto-socorro imediatamente."}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Tabela: a maleta do pai por prioridade"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ferramenta"}]}]}, {"type": "tableHeader", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Para que serve"}]}]}, {"type": "tableHeader", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Prioridade"}]}]}, {"type": "tableHeader", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Custo relativo"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Chaves de fenda e Phillips"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Apertar e soltar parafusos"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Primeira compra"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Baixo"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Martelo e trena"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Pregar, arrancar, medir"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Primeira compra"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Baixo"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Alicates e chave inglesa"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Segurar, cortar, porcas de torneira"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Primeira compra"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Baixo"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Jogo allen e nível"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Móveis desmontáveis e acabamento"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Segunda compra"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Baixo"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Chave de teste e fitas"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Elétrica básica e vedação"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Segunda compra"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Baixo"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Parafusadeira com brocas"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Furar parede e instalar"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Terceira compra"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Médio"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Óculos, luvas e lanterna de cabeça"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Proteção e visão no escuro"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Junto com a primeira"}]}]}, {"type": "tableCell", "attrs": {"colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Baixo"}]}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Com as duas primeiras linhas você já resolve metade da lista de consertos. A parafusadeira é a que mais pesa no bolso e a que mais muda o jogo; se puder, espere uma promoção e compre com duas baterias. Lembre que o valor da maleta não é o preço de cada peça, mas as chamadas de profissional que ela evita ao longo dos anos."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Checklist do pai: maleta de ferramentas"}]}, {"type": "taskList", "content": [{"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Comprar a base manual: chaves, martelo, trena e alicate"}]}]}, {"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Acrescentar chave inglesa, allen, nível e veda-rosca"}]}]}, {"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Escolher a parafusadeira com brocas e duas baterias"}]}]}, {"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Guardar tudo em maleta com trava, longe das crianças"}]}]}, {"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Desligar o disjuntor e testar antes de qualquer serviço elétrico"}]}]}, {"type": "taskItem", "attrs": {"checked": false}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ficar atento aos sinais do semáforo acima"}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Cuidar da casa com as próprias mãos é uma das formas mais antigas de um homem dizer à família que ela está segura. Você não precisa saber tudo; precisa ter a ferramenta certa, respeitar o próprio limite e começar pelo conserto mais simples. A torneira que pinga é o seu primeiro trabalho. Depois dela, a casa inteira começa a obedecer."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Continue lendo: "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/orcamento-familiar-para-quem-vai-ser-pai", "class": null, "rel": null, "target": null}}], "text": "Orçamento familiar para quem vai ser pai: passo a passo"}, {"type": "text", "text": ", "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/cortes-de-carne-para-churrasco-guia-do-pai-iniciante", "class": null, "rel": null, "target": null}}], "text": "Cortes de carne para churrasco: guia do pai iniciante"}, {"type": "text", "text": ", "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/treino-de-20-minutos-em-casa-para-pais-sem-tempo", "class": null, "rel": null, "target": null}}], "text": "Treino de 20 minutos em casa para pais sem tempo"}, {"type": "text", "text": ", "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/como-segurar-um-recem-nascido-com-seguranca", "class": null, "rel": null, "target": null}}], "text": "Como segurar um recém-nascido com segurança (e sem medo)"}, {"type": "text", "text": ", "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/rotina-do-pai-nos-primeiros-30-dias-do-bebe", "class": null, "rel": null, "target": null}}], "text": "Rotina do pai nos primeiros 30 dias do bebê"}, {"type": "text", "text": " e "}, {"type": "text", "marks": [{"type": "link", "attrs": {"href": "/post/como-ser-um-marido-presente-depois-que-o-bebe-chega", "class": null, "rel": null, "target": null}}], "text": "Como ser um marido presente depois que o bebê chega"}, {"type": "text", "text": "."}]}]}$body$::jsonb,
  $t$https://images.unsplash.com/photo-1567361808960-dec9cb578182?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&q=80&w=1080$t$,
  $t$Martelo, alicate universal, chave de fenda, jogo de chaves allen e trena sobre uma mesa de madeira$t$,
  (select id from public.categories where slug = $t$caixa-de-ferramentas-e-reparos$t$ and parent_id is null limit 1),
  (select id from public.profiles where display_name = 'Equipe Vocação de Pai' limit 1),
  'artigo',
  $faq$[{"question": "Vale comprar um kit pronto de ferramentas?", "answer": "Para começar, um kit de boa marca com maleta resolve e sai mais barato do que comprar peça por peça. O cuidado é evitar kits com muitas peças de qualidade ruim. Prefira menos itens e melhores; complete com o tempo."}, {"question": "Furadeira com fio ou sem fio?", "answer": "Para uso doméstico, uma parafusadeira-furadeira sem fio de 12 a 20 volts com função impacto atende quase tudo, inclusive parede de alvenaria com broca certa. A com fio é mais barata e mais forte para concreto, mas menos prática."}, {"question": "Posso mexer na parte elétrica da casa sozinho?", "answer": "Trocar uma tomada ou um interruptor com o disjuntor desligado e o circuito testado é tarefa básica. Qualquer coisa além disso, como quadro de distribuição, fiação nova ou chuveiro que desarma, é trabalho de eletricista. Não arrisque."}, {"question": "Onde guardar as ferramentas com criança em casa?", "answer": "Em maleta com trava ou armário alto, fora do alcance. Estilete, serra e produtos químicos ficam sempre trancados. Ensine o filho maior a usar com você, nunca sozinho."}, {"question": "Com que frequência fazer manutenção das ferramentas?", "answer": "Depois de cada uso, limpe e guarde no lugar. Uma vez por mês, confira cabos, carregue a bateria da parafusadeira e passe um pano com óleo fino nas partes metálicas para evitar ferrugem."}]$faq$::jsonb,
  $quiz$[{"question": "Qual ferramenta deve ser a primeira compra de quem está começando?", "options": ["Serra circular", "Jogo de chaves de fenda e Phillips com martelo e trena", "Esmerilhadeira", "Compressor de ar"], "correct": 1, "explanation": "Chaves, martelo, trena e alicate resolvem a maior parte dos consertos do dia a dia; as máquinas vêm depois."}, {"question": "O que fazer antes de trocar uma tomada?", "options": ["Molhar as mãos", "Desligar o disjuntor e testar o circuito com a chave de teste", "Pedir para a criança segurar a lanterna", "Nada, é rápido"], "correct": 1, "explanation": "Desligar o disjuntor e confirmar com a chave de teste que não há energia é o que separa um conserto simples de um acidente."}, {"question": "Para que serve o nível?", "options": ["Medir comprimento", "Apertar parafusos", "Conferir se prateleira e quadro estão retos", "Cortar madeira"], "correct": 2, "explanation": "O nível evita a prateleira torta e a porta que não fecha; é barato e resolve o acabamento."}, {"question": "Qual destes sinais indica que é hora de chamar um profissional?", "options": ["Prateleira torta", "Disjuntor que desarma repetidamente", "Dobradiça rangendo", "Parafuso frouxo na cadeira"], "correct": 1, "explanation": "Disjuntor que desarma várias vezes indica sobrecarga ou curto na instalação, e isso é trabalho de eletricista."}]$quiz$::jsonb,
